function findClosest(x, y, z) {
  // Walk both people one unit at a time until someone reaches z.
  let a = x;
  let b = y;
  while (a !== z && b !== z) {
    a += Math.sign(z - a);
    b += Math.sign(z - b);
  }
  if (a === z && b === z) return 0;
  return a === z ? 1 : 2;
}

