function generate(rand, size) {
  const high = size === 'large' ? 100 : 12;
  const pick = (low, top) => low + Math.floor(rand() * (top - low + 1));
  const z = pick(1, high);
  const x = pick(1, high);
  let y = pick(1, high);
  // Ties are the tricky case, so build one about a third of the time when the mirror point fits.
  const mirror = 2 * z - x;
  if (rand() < 0.35) y = mirror >= 1 && mirror <= high ? mirror : x;
  return [x, y, z];
}
